func count_common (words []string) [][]interface{} {
	var result [][]interface{}
	var temp map[string]int
	temp = make(map[string]int)
	for _, v := range words {
		temp[v]++
	}
	for k, v := range temp {
		result = append(result, []interface{}{k, v})
	}
	return result
}

