		for i := 1; i < len(l); i++ {
			for l[i] != 0 {
				if l[i] > gcd {
					gcd, l[i] = l[i], gcd % l[i]
				} else {
					gcd = gcd % l[i]
				}
			}
		}
	}
	return gcd
}

