func counting_sort (my_list []int) []int {
	var max = my_list[0]
	for _, v := range my_list {
		if v > max {
			max = v
		}
	}
	count := make([]int, max+1)
	for _, v := range my_list {
		count[v]++
	}
	for i := 1; i < len(count); i++ {
		count[i] += count[i-1]
	}
	result := make([]int, len(my_list))
	for i := len(my_list) - 1; i >= 0; i-- {
		result[count[my_list[i]]-1] = my_list[i]
		count[my_list[i]]--
	}
	return result
}

