// Write a function to split the given string with multiple delimiters by using regex.
// Examples:
// >>> multiple_split('Forces of the \ndarkness*are coming into the play.')
// >>> ['Forces of the ', 'darkness', 'are coming into the play.']
// >>> multiple_split('Mi Box runs on the \n Latest android*which has google assistance and chromecast.')
// >>> ['Mi Box runs on the ', ' Latest android', 'which has google assistance and chromecast.']
// >>> multiple_split('Certain services\nare subjected to change*over the seperate subscriptions.')
// >>> ['Certain services', 'are subjected to change', 'over the seperate subscriptions.']
func multiple_split (text string) []string {
	var result []string
	var delimiters = []string{"\n", "*"}
	for _, delimiter := range delimiters {
		result = append(result, split(text, delimiter)...)
	}
	return result
}

func split(text string, delimiter string) []string {
	var result []string
	var splitText = []string{}
	splitText = append(splitText, text)
	for {
		if len(splitText) == 0 {
			break
		}
		text = splitText[0]
		splitText = splitText[1:]
		if index := find(text, delimiter); index != -1 {
			result = append(result, text[:index])
			splitText = append(splitText, text[index+len(delimiter):])
		} else {
			result = append(result, text)
		}
	}
	return result
}

func find(text string, delimiter string) int {
	return len(text) - len(delimiter)
}

