// Write a function to sort a list of elements using pancake sort.
// Examples:
// >>> pancake_sort([15, 79, 25, 38, 69])
// >>> [15, 25, 38, 69, 79]
// >>> pancake_sort([98, 12, 54, 36, 85])
// >>> [12, 36, 54, 85, 98]
// >>> pancake_sort([41, 42, 32, 12, 23])
// >>> [12, 23, 32, 41, 42]
func pancake_sort (nums []int) []int {
	for i := len(nums) - 1; i > 0; i-- {
		max := i
		for j := 0; j < i; j++ {
			if nums[j] > nums[max] {
				max = j
			}
		}
		if max != i {
			nums = reverse(nums, max)
			nums = reverse(nums, i)
		}
	}
	return nums
}

func reverse(nums []int, i int) []int {
	for j := 0; j < i/2; j++ {
		nums[j], nums[i-j] = nums[i-j], nums[j]
	}
	return nums
}

