			if num1 / i != i {
				sum1 += num1 / i
			}
		}
	}
	for i := 1; i < int(math.Sqrt(float64(num2))); i++ {
		if num2 % i == 0 {
			sum2 += i
			if num2 / i != i {
				sum2 += num2 / i
			}
		}
	}
	return sum1 == sum2
}

