				stack = stack[:len(stack)-1]
			} else if v == '}' && stack[len(stack)-1] == '{' {
				stack = stack[:len(stack)-1]
			} else if v == ']' && stack[len(stack)-1] == '[' {
				stack = stack[:len(stack)-1]
			} else {
				return false
			}
		}
	}
	return len(stack) == 0
}

