	var dp [][]int
	for i := 0; i < m+1; i++ {
		dp = append(dp, make([]int, n+1))
	}
	for i := 1; i < m+1; i++ {
		for j := 1; j < n+1; j++ {
			if X[i-1] == Y[j-1] {
				dp[i][j] = dp[i-1][j-1] + 1
			} else {
				dp[i][j] = max(dp[i-1][j], dp[i][j-1])
			}
		}
	}
	return dp[m][n]
}

