func first_Missing_Positive (arr []int, n int) int {
	var i int
	for i = 0; i < n; i++ {
		if arr[i] == i + 1 {
			continue
		}
		if arr[i] > n || arr[i] <= 0 {
			continue
		}
		if arr[i] == arr[arr[i] - 1] {
			continue
		}
		arr[i], arr[arr[i] - 1] = arr[arr[i] - 1], arr[i]
		i--
	}
	for i = 0; i < n; i++ {
		if arr[i] != i + 1 {
			return i + 1
		}
	}
	return n + 1
}

