	for _, v := range alist {
		if reflect.TypeOf(v).Kind() == reflect.Slice {
			var temp []interface{}
			for i := 0; i < v.([]interface{})[0].(int); i++ {
				temp = append(temp, v.([]interface{})[1])
			}
			result = append(result, temp...)
		} else {
			result = append(result, v)
		}
	}
	return result
}

