// >>> even_bit_set_number(20)
// >>> 30
// >>> even_bit_set_number(30)
// >>> 30
func even_bit_set_number (n int) int {
	var result int
	for i := 0; i < 32; i++ {
		if i % 2 == 0 {
			result = result | (1 << i)
		}
	}
	return result
}

