func even_binomial_Coeff_Sum (n int) int {
	var sum int
	for i := 0; i <= n; i += 2 {
		sum += binomialCoeff(n, i)
	}
	return sum
}

func binomialCoeff(n, k int) int {
	if k > n {
		return 0
	}
	if k == 0 || k == n {
		return 1
	}
	return binomialCoeff(n-1, k-1) + binomialCoeff(n-1, k)
}

