func max_volume (s int) int {
	var max int
	for i := 1; i <= s; i++ {
		for j := 1; j <= s; j++ {
			for k := 1; k <= s; k++ {
				if i + j + k == s {
					if i * j * k > max {
						max = i * j * k
					}
				}
			}
		}
	}
	return max
}

