func get_Min_Squares_Helper (n int, squares []int) int {
	if n == 0 {
		return 0
	}
	if n < 0 {
		return -1
	}
	min := -1
	for _, square := range squares {
		if square > n {
			break
		}
		if square == n {
			return 1
		}
		if square < n {
			result := get_Min_Squares_Helper(n-square, squares)
			if result == -1 {
				continue
			}
			if min == -1 || result+1 < min {
				min = result + 1
			}
		}
	}
	return min
}

