// >>> 120
func rearrange_bigger (n int) interface{} {
	var arr []int
	for n > 0 {
		arr = append(arr, n % 10)
		n = n / 10
	}
	var res []int
	for i := 0; i < len(arr); i++ {
		for j := i + 1; j < len(arr); j++ {
			if arr[i] < arr[j] {
				arr[i], arr[j] = arr[j], arr[i]
				res = append(res, arr[i])
				res = append(res, arr[j])
				break
			}
		}
	}
	if len(res) == 0 {
		return false
	}
	var num int
	for i := 0; i < len(res); i++ {
		num = num * 10 + res[i]
	}
	return num
}

