// >>> [22, 24, 34, 39, 68, 73, 87]
// >>> shell_sort([32, 30, 16, 96, 82, 83, 74])
// >>> [16, 30, 32, 74, 82, 83, 96]
func shell_sort (my_list []int) []int {
	var n = len(my_list)
	var gap = n/2
	for gap > 0 {
		for i := gap; i < n; i++ {
			var temp = my_list[i]
			var j = i
			for j >= gap && my_list[j-gap] > temp {
				my_list[j] = my_list[j-gap]
				j -= gap
			}
			my_list[j] = temp
		}
		gap = gap/2
	}
	return my_list
}

