// >>> sumofFactors(6)
// >>> 8
func sumofFactors (n int) int {
	var sum int
	for i := 1; i <= int(math.Sqrt(float64(n))); i++ {
		if n % i == 0 {
			if i % 2 == 0 {
				sum += i
			}
			if n / i % 2 == 0 {
				sum += n / i
			}
		}
	}
	return sum
}

