// >>> radix_sort([36, 12, 24, 26, 29])
// >>> [12, 24, 26, 29, 36]
func radix_sort (nums []int) []int {
	var max int
	for _, num := range nums {
		if num > max {
			max = num
		}
	}
	var digits int
	for max > 0 {
		max /= 10
		digits++
	}
	var buckets [10][]int
	for i := 0; i < digits; i++ {
		for _, num := range nums {
			digit := num % 10
			buckets[digit] = append(buckets[digit], num)
		}
		var index int
		for j := 0; j < len(buckets); j++ {
			for _, num := range buckets[j] {
				nums[index] = num
				index++
			}
			buckets[j] = buckets[j][:0]
		}
	}
	return nums
}

